R","1184.46"],["TRO","ULS","14990.32"],["TRO","VAL","2483.23"],["TRO","VAR","779.12"],["TRO","VEN","3752.03"],["TRO","VER","5258.02"],["TRO","VIS","979.38"],["TRO","VLL","3098.46"],["TRO","VLP","9917.86"],["TRO","WIL","4570.13"],["TRO","WLG","13074.80"],["TRO","XIA","14080.60"],["TRO","YEO","14885.52"],["TRO","ZAK","3382.24"],["TRO","ZAN","9347.84"],["TRP","TSU","14213.67"],["TRP","TUN","311.45"],["TRP","TUR","3502.84"],["TRP","ULS","14296.34"],["TRP","VAL","813.23"],["TRP","VAR","3961.36"],["TRP","VEN","916.78"],["TRP","VER","5952.66"],["TRP","VIS","3297.76"],["TRP","VLL","190.27"],["TRP","VLP","9130.12"],["TRP","WIL","4873.19"],["TRP","WLG","12286.47"],["TRP","XIA","13386.62"],["TRP","YEO","14191.54"],["TRP","ZAK","475.42"],["TRP","ZAN","8653.86"],["TSU","TUN","13985.43"],["TSU","TUR","15332.56"],["TSU","ULS","87.89"],["TSU","VAL","13583.71"],["TSU","VAR","15745.76"],["TSU","VEN","14853.04"],["TSU","VER","15794.11"],["TSU","VIS","15127.48"],["TSU","VLL","14198.44"],["TSU","VLP","10053.14"],["TSU","WIL","14055.58"],["TSU","WLG","5215.28"],["TSU","XIA","833.46"],["TSU","YEO","84.19"],["TSU","ZAK","14483.25"],["TSU","ZAN","6522.88"],["TUN","TUR","3214.33"],["TUN","ULS","14007.83"],["TUN","VAL","538.70"],["TUN","VAR","3672.85"],["TUN","VEN","918.21"],["TUN","VER","5664.15"],["TUN","VIS","3009.25"],["TUN","VLL","230.54"],["TUN","VLP","8841.61"],["TUN","WIL","4584.68"],["TUN","WLG","11997.96"],["TUN","XIA","13098.11"],["TUN","YEO","13903.03"],["TUN","ZAK","548.42"],["TUN","ZAN","8365.35"],["TUR","ULS","15295.30"],["TUR","VAL","2759.07"],["TUR","VAR","1957.31"],["TUR","VEN","4027.87"],["TUR","VER","5777.58"],["TUR","VIS","203.18"],["TUR","VLL","3374.30"],["TUR","VLP","10181.93"],["TUR","WIL","5156.97"],["TUR","WLG","13338.31"],["TUR","XIA","14385.58"],["TUR","YEO","15190.50"],["TUR","ZAK","3658.08"],["TUR","ZAN","9652.82"],["ULS","VAL","13666.11"],["ULS","VAR","15828.16"],["ULS","VEN","14935.44"],["ULS","VER","15876.51"],["ULS","VIS","15209.88"],["ULS","VLL","14280.84"],["ULS","VLP","9986.47"],["ULS","WIL","14137.98"],["ULS","WLG","5301.55"],["ULS","XIA","909.67"],["ULS","YEO","117.86"],["ULS","ZAK","14565.65"],["ULS","ZAN","6631.16"],["VAL","VAR","3260.50"],["VAL","VEN","1366.30"],["VAL","VER","5249.91"],["VAL","VIS","2596.90"],["VAL","VLL","724.96"],["VAL","VLP","8420.74"],["VAL","WIL","4155.28"],["VAL","WLG","11577.10"],["VAL","XIA","12683.37"],["VAL","YEO","13488.29"],["VAL","ZAK","996.51"],["VAL","ZAN","7950.61"],["VAR","VEN","4503.59"],["VAR","VER","5592.46"],["VAR","VIS","1743.95"],["VAR","VLL","3850.02"],["VAR","VLP","10673.39"],["VAR","WIL","5143.01"],["VAR","WLG","13830.33"],["VAR","XIA","14832.53"],["VAR","YEO","15637.45"],["VAR","ZAK","4133.80"],["VAR","ZAN","10099.77"],["VEN","VER","6536.38"],["VEN","VIS","3883.37"],["VEN","VLL","739.44"],["VEN","VLP","9707.21"],["VEN","WIL","5441.75"],["VEN","WLG","12863.57"],["VEN","XIA","13969.84"],["VEN","YEO","14774.76"],["VEN","ZAK","581.34"],["VEN","ZAN","9237.08"],["VER","VIS","5728.57"],["VER","VLL","5809.33"],["VER","VLP","9079.02"],["VER","WIL","1778.56"],["VER","WLG","12236.00"],["VER","XIA","14664.09"],["VER","YEO","15469.01"],["VER","ZAK","6094.24"],["VER","ZAN","9931.30"],["VIS","VLL","3170.83"],["VIS","VLP","9978.46"],["VIS","WIL","4953.50"],["VIS","WLG","13134.84"],["VIS","XIA","14182.11"],["VIS","YEO","14987.03"],["VIS","ZAK","3454.61"],["VIS","ZAN","9449.35"],["VLL","VLP","9038.99"],["VLL","WIL","4782.06"],["VLL","WLG","12195.34"],["VLL","XIA","13295.49"],["VLL","YEO","14100.41"],["VLL","ZAK","323.20"],["VLL","ZAN","8562.73"],["VLP","WIL","7527.34"],["VLP","WLG","5437.14"],["VLP","XIA","10362.73"],["VLP","YEO","10113.46"],["VLP","ZAK","9358.09"],["VLP","ZAN","7616.56"],["WIL","WLG","10583.02"],["WIL","XIA","13018.45"],["WIL","YEO","13823.37"],["WIL","ZAK","5034.05"],["WIL","ZAN","8280.34"],["WLG","XIA","5081.38"],["WLG","YEO","5267.92"],["WLG","ZAK","12239.00"],["WLG","ZAN","7544.14"],["XIA","YEO","804.95"],["XIA","ZAK","13658.60"],["XIA","ZAN","5681.18"],["YEO","ZAK","14527.34"],["YEO","ZAN","6497.52"],["ZAK","ZAN","8865.77"]]}$seed$::jsonb as doc;
-- ═══ THE SEED (END) ═══

do $m$
declare
  c_courses   constant text := 'a9b593754530495de24d331cc3be1204';   -- public.sea_courses the lengths were measured on (prod's, before-0491)
  c_before    constant text := '3cbac251bb36faa50ba6710eadec9f7f';     -- the harbour pairs' figures 0491 replaces (prod's, before-0491)
  c_after     constant text := '8e418cd663c8c3790b94f9c4fe57e2b9';      -- the same after 0491 (the seed's)
  c_rest      constant text := '9009e9f67a735c705e577806ec0d2a53';          -- every other cell (sea places), unmoved
  v_t0        timestamptz := clock_timestamp();
  v_seed      jsonb := (select s.doc from pg_temp.seed_0491 s);
  v_n         int;
  v_moved     int;
  v_bad       text;
  v_mkt0      text;
  v_def       text;
  v_pre       text;
  v_jc0       jsonb;
  v_acl0      text := (select p.proacl::text from pg_proc p where p.oid = 'public.fleet_job_course(uuid,uuid,uuid)'::regprocedure);
  v_seen      text;
  x           record;
  v_h         record;
begin
  perform set_config('statement_timeout', '120s', true);
  perform set_config('lock_timeout', '5s', true);

  -- ── 0. GUARD: the world the lengths were measured on, the table they replace ──
  if v_seed->>'courses_md5' is distinct from c_courses
     or (select md5(string_agg(p.code || ':' || array_to_string(c.tos, ',') || ':' || array_to_string(c.offs, ',') || ':' || md5(c.pts), '|' order by p.code collate "C"))
           from public.sea_courses c join public.ports p on p.id = c.port_id) is distinct from c_courses then
    raise exception '0491 refuses: public.sea_courses is not the one the lengths were measured on (scripts/db/gen-0491-sea-lengths.mjs)';
  end if;
  create temp table hh_0491 on commit drop as
    select a.code a, e.key b, e.value v
      from public.sea_reaches a join public.ports pa on pa.id = a.port_id and pa.kind = 'HARBOUR'
     cross join lateral jsonb_each_text(a.reaches) e
     where exists (select 1 from public.ports pb where pb.code = e.key and pb.kind = 'HARBOUR');
  v_seen := (select md5(string_agg(h.a || '>' || h.b || '=' || h.v, ',' order by h.a collate "C", h.b collate "C")) from hh_0491 h);
  if v_seen is distinct from c_before then
    raise exception '0491 refuses: the harbour pairs'' figures (digest %) are not the ones it was written against (applied already, or the table moved)', v_seen;
  end if;
  create temp table seed_pairs_0491 on commit drop as
    select e->>0 a, e->>1 b, (e->>2)::numeric nm from jsonb_array_elements(v_seed->'pairs') e;
  if (select count(*) from seed_pairs_0491) <> 32128
     or exists (select 1 from seed_pairs_0491 s where s.nm is null or s.nm <= 0 or s.a collate "C" >= s.b collate "C"
                   or not exists (select 1 from hh_0491 h where h.a = s.a and h.b = s.b)) then
    raise exception '0491 self-assert FAIL: the seed is not 32,128 harbour pairs with a length each';
  end if;
  -- the market's other columns, to be held unmoved by the refill
  select md5(string_agg(row(pg.port_id, pg.good_id, pg.affinity, pg.stock, pg.stock_target, pg.production_rate, pg.drift, pg.season_mod, pg.updated_at,
                            pg.drift_slot, pg.last_regen_day, pg.demand, pg.glut, pg.base_target, pg.want_period, pg.glut_at)::text, ',' order by pg.port_id, pg.good_id))
    into v_mkt0 from public.port_goods pg;
  v_jc0 := (select jsonb_object_agg(p.code, coalesce(public.fleet_job_course(null, l.id, p.id), 'null'::jsonb))
              from public.ports l, public.ports p
             where l.code = 'LIS' and l.kind = 'HARBOUR' and p.kind = 'HARBOUR' and p.code in ('POR', 'CAD', 'LON', 'AMS', 'NAG', 'FLO', 'STG'));

  -- ── 1. THE TABLE TAKES THE SAIL'S MEASURE (both ways; one statement: the matrix is rebuilt once by its trigger) ──
  update public.sea_reaches sr set reaches = sr.reaches || n.doc
    from (select d.code, jsonb_object_agg(d.k, d.nm) doc
            from (select s.a code, s.b k, s.nm from seed_pairs_0491 s union all select s.b, s.a, s.nm from seed_pairs_0491 s) d
           group by d.code) n
   where n.code = sr.code and sr.reaches is distinct from sr.reaches || n.doc;
  get diagnostics v_n = row_count;
  v_seen := (select md5(string_agg(a.code || '>' || e.key || '=' || e.value, ',' order by a.code collate "C", e.key collate "C"))
               from public.sea_reaches a join public.ports pa on pa.id = a.port_id and pa.kind = 'HARBOUR'
              cross join lateral jsonb_each_text(a.reaches) e
              where exists (select 1 from public.ports pb where pb.code = e.key and pb.kind = 'HARBOUR'));
  if v_seen is distinct from c_after then
    raise exception '0491 self-assert FAIL: the harbour pairs'' figures (digest %) are not the seed''s after the write', v_seen;
  end if;
  if (select md5(string_agg(a.code || '>' || e.key || '=' || e.value, ',' order by a.code collate "C", e.key collate "C"))
        from public.sea_reaches a cross join lateral jsonb_each_text(a.reaches) e
       where not (exists (select 1 from public.ports pa where pa.id = a.port_id and pa.kind = 'HARBOUR')
                  and exists (select 1 from public.ports pb where pb.code = e.key and pb.kind = 'HARBOUR'))) is distinct from c_rest then
    raise exception '0491 self-assert FAIL: a sea place''s figure moved';
  end if;
  -- one figure both ways, every pair, and never shorter than the straight line between the roadsteads (0442's laws)
  select string_agg(a.code || '-' || b.code, ' '), count(*) into v_bad, v_n
    from public.sea_reaches a join public.sea_reaches b on b.code <> a.code
   where (a.reaches ->> b.code) is null or (a.reaches ->> b.code)::numeric <> (b.reaches ->> a.code)::numeric
      or (a.reaches ->> b.code)::numeric < voyage.gc_distance_nm(a.roadstead_lat::float8, a.roadstead_lon::float8, b.roadstead_lat::float8, b.roadstead_lon::float8) - 0.1;
  if v_n > 0 then
    raise exception '0491 self-assert FAIL: % pair(s) are not one distance both ways, or are shorter than the straight line: %', v_n, left(v_bad, 400);
  end if;
  -- THE MEASURE, LIVE: a sample (every pair whose codes hash to 00, and the longest move, ARI-AYU), sailed both ways through the SAIL's own
  -- function, equals the table to the hundredth
  select string_agg(format('%s-%s table %s sailed %s/%s', s.a, s.b, s.t, s.ab, s.ba), '; '), count(*) filter (where s.t is distinct from s.ab or s.t is distinct from s.ba), count(*)
    into v_bad, v_n, v_moved
    from (select q.a, q.b, (ra.reaches ->> q.b)::numeric t,
                 (select sum((g ->> 'nm')::numeric) from jsonb_array_elements(voyage.segments_from_course(public.sea_course(pa.id, pb.id))) g) ab,
                 (select sum((g ->> 'nm')::numeric) from jsonb_array_elements(voyage.segments_from_course(public.sea_course(pb.id, pa.id))) g) ba
            from seed_pairs_0491 q
            join public.ports pa on pa.code = q.a and pa.kind = 'HARBOUR' join public.ports pb on pb.code = q.b and pb.kind = 'HARBOUR'
            join public.sea_reaches ra on ra.port_id = pa.id
           where left(md5(q.a || q.b), 2) = '00' or (q.a, q.b) = ('ARI', 'AYU')) s;
  if v_n > 0 or v_moved < 50 then
    raise exception '0491 self-assert FAIL: % of % sampled pair(s) sail another length than the table: %', v_n, v_moved, left(v_bad, 600);
  end if;
  -- the matrix the readers read is the one built from the table (its trigger kept it)
  if not exists (select 1 from public.sea_reach_matrix m, public.sea_reach_matrix_build() b
                  where m.id = 1 and m.ids = b.ids and m.codes = b.codes and m.nm = b.nm) then
    raise exception '0491 self-assert FAIL: public.sea_reach_matrix is not the one built from the new table';
  end if;
  raise notice '0491: the harbour pairs'' figures are the SAIL''s measure; % sampled pair(s) re-measured live, both ways, equal', v_moved;

  -- ── 2. THE PRICES FOLLOW: every market row's haul is the one derivation's answer again (0173; 0442's and 0446's refill) ──
  update public.port_goods pg set haul_nm = h.haul_nm, haul = h.haul
    from world.haul_rows() h
   where h.port_id = pg.port_id and h.good_id = pg.good_id and (pg.haul_nm, pg.haul) is distinct from (h.haul_nm, h.haul);
  get diagnostics v_moved = row_count;
  if exists (select 1 from public.port_goods pg join world.haul_rows() h on h.port_id = pg.port_id and h.good_id = pg.good_id
              where (pg.haul_nm, pg.haul) is distinct from (h.haul_nm, h.haul)) then
    raise exception '0491 self-assert FAIL: a market row''s haul is not world.haul_rows()''s answer after the refill';
  end if;
  if (select md5(string_agg(row(pg.port_id, pg.good_id, pg.affinity, pg.stock, pg.stock_target, pg.production_rate, pg.drift, pg.season_mod, pg.updated_at,
                                pg.drift_slot, pg.last_regen_day, pg.demand, pg.glut, pg.base_target, pg.want_period, pg.glut_at)::text, ',' order by pg.port_id, pg.good_id))
        from public.port_goods pg) is distinct from v_mkt0 then
    raise exception '0491 self-assert FAIL: the refill moved a market column other than haul_nm / haul';
  end if;
  raise notice '0491: % market row(s) refilled from world.haul_rows(); every other market column unmoved', v_moved;

  -- ── 3. THE COURSE A JOB SAILS: the stored course first (two hunks; each occurs once and reverses) ──
  create temp table hunks_0491 (fn text, ord int, old text, new text) on commit drop;
  insert into hunks_0491 values
  ('public.fleet_job_course(uuid,uuid,uuid)', 1,
$h$  select coalesce(
    (select k.course from public.npc_known_legs(p_from) k where k.to_port = p_to),$h$,
$h$  select coalesce(
    -- 0491 (sea_courses_enabled): FIRST the stored course between the two (public.sea_course), the course the board's miles are measured
    -- on (public.sea_reaches, 0491), so the trip a card quotes is the trip she sails; a lane, a coast course or her own voyage only where none
    case when public.sea_courses_on() then public.sea_course(p_from, p_to) end,
    (select k.course from public.npc_known_legs(p_from) k where k.to_port = p_to),$h$),
  ('public.fleet_job_course(uuid,uuid,uuid)', 2,
$h$      limit 1),
    -- 0482 (sea_courses_enabled): else the stored course between the two (public.sea_course: the browser's own, roadstead to roadstead)
    case when public.sea_courses_on() then public.sea_course(p_from, p_to) end)$h$,
$h$      limit 1))$h$);

  for v_h in select h.fn from hunks_0491 h group by h.fn order by h.fn loop
    v_def := replace(pg_get_functiondef(v_h.fn::regprocedure), E'\r', '');
    v_pre := v_def;
    for x in select * from hunks_0491 h where h.fn = v_h.fn order by h.ord loop
      v_n := (length(v_def) - length(replace(v_def, x.old, ''))) / length(x.old);
      if v_n <> 1 then
        raise exception '0491 self-assert FAIL: hunk % of % occurs % time(s), not once: the deployed body is not what this file was written against', x.ord, x.fn, v_n;
      end if;
      v_def := replace(v_def, x.old, x.new);
    end loop;
    execute v_def;
    v_def := replace(pg_get_functiondef(v_h.fn::regprocedure), E'\r', '');
    for x in select * from hunks_0491 h where h.fn = v_h.fn order by h.ord desc loop
      if (length(v_def) - length(replace(v_def, x.new, ''))) / length(x.new) <> 1 then
        raise exception '0491 self-assert FAIL: hunk % of % is not in the new body once', x.ord, x.fn;
      end if;
      v_def := replace(v_def, x.new, x.old);
    end loop;
    if v_def <> v_pre then
      raise exception '0491 self-assert FAIL: % does not reverse to its pre-image', v_h.fn;
    end if;
  end loop;
  if (select p.prosecdef and p.provolatile = 's' and p.proconfig::text = '{"search_path=public, pg_temp"}' and p.proacl::text is not distinct from v_acl0
        from pg_proc p where p.oid = 'public.fleet_job_course(uuid,uuid,uuid)'::regprocedure) is not true then
    raise exception '0491 self-assert FAIL: public.fleet_job_course lost its definer, volatility, search path or grants';
  end if;
  -- lit, the stored course wherever one is stored; dark, the answer it gave before
  if public.sea_courses_on() then
    if exists (select 1 from public.ports l, public.ports p
                where l.code = 'LIS' and l.kind = 'HARBOUR' and p.kind = 'HARBOUR' and p.code in ('POR', 'CAD', 'LON', 'AMS', 'NAG', 'FLO', 'STG')
                  and public.fleet_job_course(null, l.id, p.id) is distinct from public.sea_course(l.id, p.id)) then
      raise exception '0491 self-assert FAIL: lit, a job from Lisbon does not sail the stored course';
    end if;
  elsif (select jsonb_object_agg(p.code, coalesce(public.fleet_job_course(null, l.id, p.id), 'null'::jsonb))
           from public.ports l, public.ports p
          where l.code = 'LIS' and l.kind = 'HARBOUR' and p.kind = 'HARBOUR' and p.code in ('POR', 'CAD', 'LON', 'AMS', 'NAG', 'FLO', 'STG')) is distinct from v_jc0 then
    raise exception '0491 self-assert FAIL: dark, a job from Lisbon sails another course than before';
  end if;

  raise notice '0491 self-assert ok: one distance (the SAIL''s), prices refilled, the job carries the stored course when lit; % ms',
    round(extract(epoch from clock_timestamp() - v_t0) * 1000);
end
$m$;

-- ── THE NEWS (0347's law) ──
select public.news_update('0491', 'Long trips: true days and prices', '먼 항해: 실제 일수와 가격');
